function draw(ctx, state, t) {
  var w = state.w, h = state.h, a = state.alpha, c = state.c, g, f = [], best = 1, top = 0;
  function fx(v) { return "" + Math.round(v * 100) / 100; }
  for (g = 1; g <= 12; g++) { f[g] = (1 - Math.pow(a, g + 1)) / ((1 - a) * (g * c + 1)); if (f[g] > f[best]) best = g; top = Math.max(top, f[g]); }
  top = Math.max(top, 1.2) * 1.1;
  var x0 = 50, y0 = h - 30, gw = w - 80, gh = h - 60;
  function X(g) { return x0 + (g - 1) / 11 * gw; }
  function Y(v) { return y0 - v / top * gh; }
  ctx.fillStyle = "#f7f5f0"; ctx.fillRect(0, 0, w, h);
  ctx.strokeStyle = "#bbb"; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x0 + gw, y0); ctx.moveTo(x0, y0); ctx.lineTo(x0, y0 - gh); ctx.stroke();
  ctx.strokeStyle = "#c0392b"; ctx.beginPath(); ctx.moveTo(x0, Y(1)); ctx.lineTo(x0 + gw, Y(1)); ctx.stroke();
  ctx.fillStyle = "#c0392b"; ctx.font = "11px sans-serif"; ctx.fillText("1× (no gain)", x0 + gw - 70, Y(1) - 4);
  ctx.strokeStyle = "#1f4b99"; ctx.lineWidth = 2.5; ctx.beginPath();
  for (g = 1; g <= 12; g++) { if (g === 1) ctx.moveTo(X(g), Y(f[g])); else ctx.lineTo(X(g), Y(f[g])); }
  ctx.stroke();
  ctx.fillStyle = "#1f4b99"; for (g = 1; g <= 12; g++) { ctx.beginPath(); ctx.arc(X(g), Y(f[g]), 3, 0, 2 * Math.PI); ctx.fill(); }
  ctx.fillStyle = "#2e7d32"; ctx.beginPath(); ctx.arc(X(best), Y(f[best]), 7, 0, 2 * Math.PI); ctx.fill();
  ctx.fillStyle = "#555"; for (g = 1; g <= 12; g++) ctx.fillText("" + g, X(g) - 3, y0 + 14);
  ctx.fillText("draft length γ", x0 + gw / 2 - 30, h - 2);
  ctx.fillStyle = "#222"; ctx.font = "14px sans-serif";
  ctx.fillText("best γ = " + best + "   speedup ≈ " + fx(f[best]) + "×   tokens per target call ≈ " + fx((1 - Math.pow(a, best + 1)) / (1 - a)), x0 + 6, 20);
}

function draw(ctx, state, t) {
  var w = state.w, h = state.h, s = state.s, L = Math.pow(2, state.logl), D = 128, b = 10000, al = 1, be = 32, d;
  var n = D / 2, bw = (w - 70) / n, y0 = h * 0.62, gh = h * 0.55, lo = 0, hi = Math.log(2 * Math.PI * Math.pow(b, 1)) + 0.5;
  function Y(lam) { return y0 - (Math.log(lam) - lo) / (hi - lo) * gh; }
  ctx.fillStyle = "#f7f5f0"; ctx.fillRect(0, 0, w, h);
  var cnt0 = 0, cnt1 = 0;
  for (d = 0; d < n; d++) {
    var lam = 2 * Math.PI * Math.pow(b, 2 * d / D), r = L / lam, g = r < al ? 0 : (r > be ? 1 : (r - al) / (be - al));
    if (g === 0) cnt0++; if (g === 1) cnt1++;
    ctx.fillStyle = g === 1 ? "#1f4b99" : (g === 0 ? "#e67e22" : "#8e44ad");
    ctx.globalAlpha = g === 0 || g === 1 ? 1 : 0.45 + 0.5 * g;
    ctx.fillRect(50 + d * bw, Y(lam), bw - 1, y0 - Y(lam));
    var ratio = (1 - g) / s + g;
    ctx.globalAlpha = 1; ctx.fillStyle = "#333";
    ctx.fillRect(50 + d * bw, h - 12 - ratio * (h * 0.22), bw - 1, 2);
  }
  ctx.strokeStyle = "#c0392b"; ctx.lineWidth = 1.5; ctx.beginPath(); ctx.moveTo(45, Y(L)); ctx.lineTo(w - 15, Y(L)); ctx.stroke();
  ctx.strokeStyle = "#999"; ctx.beginPath(); ctx.moveTo(45, Y(L / be)); ctx.lineTo(w - 15, Y(L / be)); ctx.stroke();
  ctx.font = "11px sans-serif"; ctx.fillStyle = "#c0392b"; ctx.fillText("λ = L = " + L, w - 95, Y(L) - 4);
  ctx.fillStyle = "#777"; ctx.fillText("λ = L/32", w - 70, Y(L / be) + 12);
  ctx.fillStyle = "#444"; ctx.fillText("wavelength λ (log)", 4, 12); ctx.fillText("θ_new / θ  (1 = untouched, 1/s = interpolated)", 50, y0 + 18);

  ctx.font = "12px sans-serif"; ctx.fillStyle = "#1f4b99"; ctx.fillText("untouched " + cnt1, 60, 28);
  ctx.fillStyle = "#8e44ad"; ctx.fillText("blended " + (n - cnt0 - cnt1), 160, 28);
  ctx.fillStyle = "#e67e22"; ctx.fillText("interpolated ÷" + s + ": " + cnt0, 250, 28);
}

function draw(ctx, state, t) {
  var w = state.w, h = state.h, n = 48, A = -1, i, seed = 31, x = [], keep = [], hs = [], hh = 0;
  function rnd() { seed = (seed * 1103515245 + 12345) % 2147483648; return seed / 2147483648; }
  for (i = 0; i < n; i++) { keep[i] = i === 6 || i === 20 || i === 34; x[i] = keep[i] ? (i === 20 ? -0.8 : (i === 6 ? 0.9 : 0.4)) : (rnd() - 0.5) * 1.6; }
  for (i = 0; i < n; i++) { var d = keep[i] ? state.dkeep : state.dnoise, g = Math.exp(d * A); hh = g * hh + (1 - g) * x[i]; hs[i] = hh; }
  var x0 = 30, gw = w - 50, bw = gw / n, mid = h * 0.5, sc = h * 0.38;
  ctx.fillStyle = "#f7f5f0"; ctx.fillRect(0, 0, w, h);
  ctx.strokeStyle = "#ccc"; ctx.lineWidth = 1; ctx.beginPath(); ctx.moveTo(x0, mid); ctx.lineTo(x0 + gw, mid); ctx.stroke();
  for (i = 0; i < n; i++) {
    ctx.fillStyle = keep[i] ? "#e67e22" : "#c9c4ba";
    var v = x[i] * sc; ctx.fillRect(x0 + i * bw + 2, v > 0 ? mid - v : mid, bw - 4, Math.abs(v));
  }
  ctx.strokeStyle = "#1f4b99"; ctx.lineWidth = 3; ctx.beginPath();
  for (i = 0; i < n; i++) { var px = x0 + i * bw + bw / 2, py = mid - hs[i] * sc; if (i === 0) ctx.moveTo(px, py); else ctx.lineTo(px, py); }
  ctx.stroke();
  ctx.font = "12px sans-serif"; ctx.fillStyle = "#1f4b99"; ctx.fillText("state h", x0, 16);
  ctx.fillStyle = "#e67e22"; ctx.fillText("tokens to keep", x0 + 70, 16);
  ctx.fillStyle = "#777"; ctx.fillText("noise", x0 + 175, 16);
  ctx.fillStyle = "#333"; ctx.fillText("time →", w - 60, h - 6);
}

function draw(ctx, state, t) {
  var w = state.w, h = state.h, a = state.alpha, n = 8, j, k;
  var xm = [1.2, 0.8, 40, 1.0, 0.6, 25, 1.4, 0.9], wm = [0.5, 0.7, 0.4, 0.6, 0.8, 0.5, 0.3, 0.6];
  function fx(v) { return "" + Math.round(v * 1000) / 1000; }
  function q(v, m) { var st = m / 127; return Math.abs(v - Math.round(v / st) * st) / v; }
  function run(al, sx, sw) {
    var mx = 0, mw = 0, ex = 0, ew = 0;
    for (j = 0; j < n; j++) { var s = Math.pow(xm[j], al) / Math.pow(wm[j], 1 - al); sx[j] = xm[j] / s; sw[j] = wm[j] * s; mx = Math.max(mx, sx[j]); mw = Math.max(mw, sw[j]); }
    for (j = 0; j < n; j++) { ex = Math.max(ex, q(sx[j] * 0.37, mx)); ew = Math.max(ew, q(sw[j] * 0.37, mw)); }
    return [ex, ew, mx, mw];
  }
  var SX = [], SW = [], r = run(a, SX, SW), prod = 0, prod0 = 0;
  for (j = 0; j < n; j++) { prod += SX[j] * SW[j]; prod0 += xm[j] * wm[j]; }
  ctx.fillStyle = "#f7f5f0"; ctx.fillRect(0, 0, w, h);
  function panel(x0, vals, m, col, label, e) {
    var pw = w * 0.28, ph = h * 0.42, y0 = 34 + ph, bw = pw / n;
    ctx.fillStyle = "#333"; ctx.font = "13px sans-serif"; ctx.fillText(label, x0, 20);
    for (j = 0; j < n; j++) { ctx.fillStyle = col; ctx.fillRect(x0 + j * bw + 2, y0 - ph * vals[j] / m, bw - 4, ph * vals[j] / m); }
    ctx.fillStyle = e > 0.05 ? "#c0392b" : "#2e7d32"; ctx.font = "12px sans-serif";
    ctx.fillText("worst 8-bit error: " + Math.round(e * 1000) / 10 + "%", x0, y0 + 18);
  }
  panel(16, SX, r[2], "#1f4b99", "activations X / s", r[0]);
  panel(w * 0.34, SW, r[3], "#8e44ad", "weights s · W", r[1]);
  var gx = w * 0.68, gy = 30, gw = w * 0.29, gh = h * 0.42, e, top = 0.2;
  ctx.fillStyle = "#333"; ctx.font = "13px sans-serif"; ctx.fillText("error vs α", gx, 20);
  ctx.strokeStyle = "#bbb"; ctx.lineWidth = 1; ctx.strokeRect(gx, gy, gw, gh);
  for (var c = 0; c < 3; c++) {
    ctx.strokeStyle = c === 0 ? "#1f4b99" : (c === 1 ? "#8e44ad" : "#222"); ctx.lineWidth = c === 2 ? 2.5 : 1.5; ctx.beginPath();
    for (k = 0; k <= 40; k++) { e = run(k / 40, [], []); var v = c === 2 ? Math.max(e[0], e[1]) : e[c];
      var py = gy + gh * (1 - Math.min(v, top) / top); if (k === 0) ctx.moveTo(gx + gw * k / 40, py); else ctx.lineTo(gx + gw * k / 40, py); }
    ctx.stroke();
  }
  ctx.fillStyle = "#c0392b"; ctx.beginPath(); ctx.arc(gx + gw * a, gy + gh * (1 - Math.min(Math.max(r[0], r[1]), top) / top), 5, 0, 2 * Math.PI); ctx.fill();
  ctx.font = "11px sans-serif"; ctx.fillStyle = "#555"; ctx.fillText("0", gx, gy + gh + 12); ctx.fillText("1", gx + gw - 6, gy + gh + 12);
  ctx.fillText("black = worse of the two", gx, gy + gh + 26);
  ctx.fillStyle = "#333"; ctx.font = "12px sans-serif";
  ctx.fillText("Σ_j X_j·W_j before = " + fx(prod0) + "   after = " + fx(prod) + "   (the layer output does not change)", 16, h - 10);
}
